/**
 * Session and data-source orchestration.
 *
 * Two ways to use the app:
 * - Live mode: Supabase configured + signed in; lessons come from the real
 *   library (generated by backend jobs).
 * - Sample mode: the bundled placeholder library, clearly labelled in the UI.
 *   It is automatic when Supabase is not configured, and also available as an
 *   explicit escape hatch ("Explore sample lessons") from the welcome screen.
 */
import React, {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from 'react';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { isSupabaseConfigured } from '../lib/env';
import { getSupabase } from '../lib/supabase';
import { sampleApi } from '../data/sample-api';
import { supabaseApi } from '../data/supabase-api';
import type { LumioApi } from '../data/types';

const SAMPLE_MODE_KEY = 'lumio.sampleMode.v1';

export type SessionStatus =
  | 'loading'
  | 'signedOut'
  | 'needsOnboarding'
  | 'ready'
  | 'error';

export type AuthResult =
  | { ok: true; needsConfirmation?: boolean }
  | { ok: false; message: string };

export type SessionState = {
  status: SessionStatus;
  errorMessage: string | null;
  email: string | null;
  userId: string | null;
  useSample: boolean;
  liveConfigured: boolean;
  api: LumioApi;
  signIn: (email: string, password: string) => Promise<AuthResult>;
  signUp: (email: string, password: string) => Promise<AuthResult>;
  signOut: () => Promise<void>;
  enterSampleMode: () => Promise<void>;
  exitSampleMode: () => Promise<void>;
  markOnboarded: () => void;
  retry: () => void;
};

const SessionContext = createContext<SessionState | null>(null);

function friendlyAuthError(message: string): string {
  const lower = message.toLowerCase();
  if (lower.includes('invalid login credentials')) {
    return 'Email or password is incorrect.';
  }
  if (lower.includes('email not confirmed')) {
    return 'Please confirm your email first — check your inbox for the confirmation link.';
  }
  if (lower.includes('already registered')) {
    return 'An account with this email already exists. Sign in instead.';
  }
  if (lower.includes('rate limit')) {
    return 'Too many attempts. Please wait a moment and try again.';
  }
  if (lower.includes('password')) {
    return 'That password does not meet the requirements (at least 6 characters).';
  }
  return message;
}

export function SessionProvider({ children }: { children: React.ReactNode }) {
  const [bootKey, setBootKey] = useState(0);
  const [status, setStatus] = useState<SessionStatus>('loading');
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [email, setEmail] = useState<string | null>(null);
  const [userId, setUserId] = useState<string | null>(null);
  const [useSample, setUseSample] = useState(!isSupabaseConfigured);

  /** Decide which state the signed-in user should see next. */
  const evaluateProfile = useCallback(async (uid: string, userEmail: string | null) => {
    setUserId(uid);
    setEmail(userEmail);
    const { data, error } = await getSupabase()
      .from('profiles')
      .select('onboarding_completed_at')
      .eq('id', uid)
      .maybeSingle();
    if (error) {
      setStatus('error');
      setErrorMessage(`Could not load your profile: ${error.message}`);
      return;
    }
    const completedAt =
      data && typeof data.onboarding_completed_at === 'string'
        ? data.onboarding_completed_at
        : null;
    setStatus(completedAt ? 'ready' : 'needsOnboarding');
  }, []);

  useEffect(() => {
    let cancelled = false;

    async function boot() {
      setStatus('loading');
      setErrorMessage(null);

      if (!isSupabaseConfigured) {
        // Sample mode is the only option without a configured backend.
        const profile = await sampleApi.getProfile();
        if (!cancelled) {
          setUseSample(true);
          setStatus(profile.interests.length > 0 ? 'ready' : 'signedOut');
          setUserId(null);
          setEmail(null);
        }
        return;
      }

      const sampleFlag = await AsyncStorage.getItem(SAMPLE_MODE_KEY);
      if (sampleFlag === '1') {
        const profile = await sampleApi.getProfile();
        if (!cancelled) {
          setUseSample(true);
          setStatus(profile.interests.length > 0 ? 'ready' : 'signedOut');
        }
        return;
      }

      const { data, error } = await getSupabase().auth.getSession();
      if (cancelled) {
        return;
      }
      if (error) {
        setStatus('error');
        setErrorMessage(`Could not restore your session: ${error.message}`);
        return;
      }
      const session = data.session;
      if (!session) {
        setUseSample(false);
        setStatus('signedOut');
        return;
      }
      setUseSample(false);
      await evaluateProfile(session.user.id, session.user.email ?? null);
    }

    boot();

    return () => {
      cancelled = true;
    };
  }, [bootKey, evaluateProfile]);

  useEffect(() => {
    if (!isSupabaseConfigured) {
      return undefined;
    }
    const { data } = getSupabase().auth.onAuthStateChange((event, session) => {
      if (event === 'SIGNED_OUT') {
        setUserId(null);
        setEmail(null);
        setStatus(current => (current === 'error' ? 'signedOut' : 'signedOut'));
      } else if (event === 'SIGNED_IN' && session && useSample === false) {
        evaluateProfile(session.user.id, session.user.email ?? null);
      }
    });
    return () => {
      data.subscription.unsubscribe();
    };
  }, [evaluateProfile, useSample]);

  const signIn = useCallback(async (inputEmail: string, password: string): Promise<AuthResult> => {
    const value = inputEmail.trim();
    if (!value || !password) {
      return { ok: false, message: 'Enter your email and password.' };
    }
    const { data, error } = await getSupabase().auth.signInWithPassword({
      email: value,
      password,
    });
    if (error) {
      return { ok: false, message: friendlyAuthError(error.message) };
    }
    setUseSample(false);
    await AsyncStorage.removeItem(SAMPLE_MODE_KEY);
    if (data.user) {
      await evaluateProfile(data.user.id, data.user.email ?? value);
    }
    return { ok: true };
  }, [evaluateProfile]);

  const signUp = useCallback(async (inputEmail: string, password: string): Promise<AuthResult> => {
    const value = inputEmail.trim();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) {
      return { ok: false, message: 'Enter a valid email address.' };
    }
    if (password.length < 6) {
      return { ok: false, message: 'Use a password with at least 6 characters.' };
    }
    const { data, error } = await getSupabase().auth.signUp({ email: value, password });
    if (error) {
      return { ok: false, message: friendlyAuthError(error.message) };
    }
    setUseSample(false);
    await AsyncStorage.removeItem(SAMPLE_MODE_KEY);
    if (data.session && data.user) {
      await evaluateProfile(data.user.id, data.user.email ?? value);
      return { ok: true };
    }
    // Email confirmation is enabled on the project: no session yet.
    return { ok: true, needsConfirmation: true };
  }, [evaluateProfile]);

  const signOut = useCallback(async () => {
    await getSupabase().auth.signOut();
    setUserId(null);
    setEmail(null);
    setStatus('signedOut');
  }, []);

  const enterSampleMode = useCallback(async () => {
    await AsyncStorage.setItem(SAMPLE_MODE_KEY, '1');
    const profile = await sampleApi.getProfile();
    setUseSample(true);
    setUserId(null);
    setEmail(null);
    setStatus(profile.interests.length > 0 ? 'ready' : 'signedOut');
  }, []);

  const exitSampleMode = useCallback(async () => {
    await AsyncStorage.removeItem(SAMPLE_MODE_KEY);
    setBootKey(key => key + 1);
  }, []);

  const markOnboarded = useCallback(() => {
    setStatus('ready');
  }, []);

  const retry = useCallback(() => {
    setBootKey(key => key + 1);
  }, []);

  const api = useSample || !isSupabaseConfigured ? sampleApi : supabaseApi;

  const value = useMemo<SessionState>(
    () => ({
      status,
      errorMessage,
      email,
      userId,
      useSample,
      liveConfigured: isSupabaseConfigured,
      api,
      signIn,
      signUp,
      signOut,
      enterSampleMode,
      exitSampleMode,
      markOnboarded,
      retry,
    }),
    [
      status,
      errorMessage,
      email,
      userId,
      useSample,
      api,
      signIn,
      signUp,
      signOut,
      enterSampleMode,
      exitSampleMode,
      markOnboarded,
      retry,
    ],
  );

  return <SessionContext.Provider value={value}>{children}</SessionContext.Provider>;
}

export function useSession(): SessionState {
  const context = useContext(SessionContext);
  if (!context) {
    throw new Error('useSession must be used inside SessionProvider');
  }
  return context;
}

export function useApi(): LumioApi {
  return useSession().api;
}
